function parseJson(text) {
  const cleaned = text.replace(/```json/g, '').replace(/```/g, '').trim();
  return JSON.parse(cleaned);
}

const riskRaw = $('Risk Assessment').item.json.message.content;
const strategicRaw = $('Strategic Analysis').item.json.message.content;

const riskParsed = parseJson(riskRaw);
const strategicParsed = parseJson(strategicRaw);

const risk_scores = {};
const reward_scores = {};
const feasibility_scores = {};
const timeline_scores = {};

for (const option of Object.keys(riskParsed)) {
  risk_scores[option] = riskParsed[option].risk;
}
for (const option of Object.keys(strategicParsed)) {
  reward_scores[option] = strategicParsed[option].reward;
  feasibility_scores[option] = strategicParsed[option].feasibility;
  timeline_scores[option] = strategicParsed[option].timeline;
}

return [{ json: { risk_scores, reward_scores, feasibility_scores, timeline_scores } }];

